function detectLang(){
 try{const saved=localStorage.getItem('dook-lang');if(supportedLangs.includes(saved))return saved}catch{}
 const browser=(navigator.language||'en').slice(0,2).toLowerCase();
 return supportedLangs.includes(browser)?browser:'en';
}
let currentLang=detectLang();
function t(key,vars){
 let str=translations[currentLang]?.[key]??translations.en[key]??key;
 if(vars)for(const [k,v] of Object.entries(vars))str=str.replaceAll('{'+k+'}',v);
 return str;
}
function applyStaticTranslations(){
 document.title=t('meta.title');
 document.querySelector('meta[name="description"]')?.setAttribute('content',t('meta.description'));
 document.querySelector('.brand')?.setAttribute('aria-label',t('nav.homeAria'));
 document.querySelector('.mobile-toggle')?.setAttribute('aria-label',t('nav.toggleAria'));
 document.querySelector('.nav-label')&&(document.querySelector('.nav-label').textContent=t('nav.eyebrow'));
 document.querySelector('.close')?.setAttribute('aria-label',t('modal.closeAria'));
 const navKeys=['home','collection','about','news','contact'];
 document.querySelectorAll('nav a[data-page]').forEach((a,i)=>{if(navKeys[i]&&a.firstChild?.nodeType===Node.TEXT_NODE)a.firstChild.textContent=t('nav.'+navKeys[i])+' '});
 const adminNav=document.querySelector('[data-admin-nav]');if(adminNav?.firstChild?.nodeType===Node.TEXT_NODE)adminNav.firstChild.textContent=t('common.administration')+' ';
 document.querySelectorAll('[data-set-lang]').forEach(b=>b.toggleAttribute('aria-current',b.dataset.setLang===currentLang));
 const banner=document.querySelector('#cookie-banner');
 if(banner){
  const p=banner.querySelector('p');if(p)p.innerHTML=t('cookie.bannerText');
  const accept=banner.querySelector('[data-cookie-accept]');if(accept)accept.textContent=t('cookie.accept');
  const decline=banner.querySelector('[data-cookie-decline]');if(decline)decline.textContent=t('cookie.decline');
 }
}
function setLang(lang){
 if(!supportedLangs.includes(lang)||lang===currentLang)return;
 currentLang=lang;
 try{localStorage.setItem('dook-lang',lang)}catch{}
 document.documentElement.lang=lang;
 applyStaticTranslations();
 if(typeof render==='function')render();
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-set-lang]');if(b)setLang(b.dataset.setLang)});
document.documentElement.lang=currentLang;
applyStaticTranslations();
